namespace FusionOS.Modules.Sales.Application.Invoices.Contracts;

/// <summary>
/// Abstraction over the GST Invoice Registration Portal (IRP) — the government API an
/// invoice's IRN (Invoice Reference Number) and QR code are actually generated by. Real
/// submission requires a GSP (GST Suvidha Provider) account, which is an external
/// credential/contract this codebase cannot obtain on its own — see
/// Infrastructure/Gst/SandboxGstIrpClient for the fake implementation registered by default
/// so this feature is testable without live GSTN credentials. A real HTTP-backed
/// implementation slots in behind this same interface once a GSP account exists, without
/// GenerateEInvoiceCommandHandler changing at all.
///
/// The GSTN portal has required MFA on this kind of API access since 1 Apr 2025 — a real
/// implementation's auth/token-refresh design must assume a short-lived session token
/// obtained via an MFA-capable auth step, not a static long-lived API key.
/// </summary>
public interface IGstIrpClient
{
    Task<GstIrpSubmissionResult> SubmitInvoiceAsync(GstIrpInvoicePayload payload, CancellationToken cancellationToken = default);
}

public sealed record GstIrpInvoicePayload(
    Guid CompanyId,
    Guid InvoiceId,
    DateTimeOffset InvoiceDate,
    decimal TotalAmount,
    IReadOnlyList<GstIrpInvoiceLine> Lines);

public sealed record GstIrpInvoiceLine(Guid ProductId, decimal Quantity, decimal UnitPrice, decimal TaxAmount);

public sealed record GstIrpSubmissionResult(string Irn, string QrCodePayload, string AckNumber, DateTimeOffset GeneratedAt);
